parameters.command:
=set -euo pipefail; ROOT="${CHELSEA_PRIVACY_EXPORTS_ROOT:-/files/chelsea_privacy_exports}"; REQUEST='{{ $json.requestId }}'; PRINCIPAL='{{ $json.principalKey }}'; ACTOR='{{ $json.telegramActorId }}'; case "$REQUEST" in *[!A-Za-z0-9_.:-]*|'') exit 2;; esac; case "$PRINCIPAL" in tgactor_[a-f0-9]*) ;; *) exit 2;; esac; case "$ACTOR" in *[!0-9]*|'') exit 2;; esac; OUTDIR="$ROOT/$REQUEST/delivery"; WORK="$OUTDIR/work"; BUNDLE="$OUTDIR/chelsea_privacy_export_${REQUEST}.tar.gz"; install -d -m 0700 "$WORK"; BODY=$(printf '{"p_request_id":"%s","p_principal_key":"%s","p_actor_id":%s}' "$REQUEST" "$PRINCIPAL" "$ACTOR"); curl -fsS --connect-timeout 10 --max-time 120 -X POST -H "Content-Type: application/json" -H "apikey: $CHELSEA_SUPABASE_SERVICE_ROLE_KEY" -H "Authorization: Bearer $CHELSEA_SUPABASE_SERVICE_ROLE_KEY" --data "$BODY" "${CHELSEA_SUPABASE_URL%/}/rest/v1/rpc/chelsea_privacy_export_delivery_payload_v1" -o "$WORK/payload.json"; ROOT_ENV="$ROOT" WORK_ENV="$WORK" node <<'NODE'
const fs=require('fs'),path=require('path');const root=process.env.ROOT_ENV,work=process.env.WORK_ENV;let raw=JSON.parse(fs.readFileSync(path.join(work,'payload.json'),'utf8'));if(Array.isArray(raw))raw=raw[0];if(!raw||raw.success!==true)throw new Error('delivery_payload_invalid');fs.writeFileSync(path.join(work,'supabase.json'),JSON.stringify(raw.supabaseExport||{},null,2));fs.writeFileSync(path.join(work,'data_tables.json'),JSON.stringify(raw.targetReceipts?.data_tables||{},null,2));fs.writeFileSync(path.join(work,'manifest.json'),JSON.stringify({requestId:raw.requestId,manifest:raw.manifest,targetReceipts:raw.targetReceipts,expiresAt:raw.expiresAt},null,2));function copySafe(src,name){if(!src)return;const resolved=fs.realpathSync(src),rr=fs.realpathSync(root);if(!(resolved===rr||resolved.startsWith(rr+path.sep)))throw new Error('artifact_path_outside_root');if(fs.lstatSync(resolved).isSymbolicLink())throw new Error('artifact_symlink_blocked');fs.copyFileSync(resolved,path.join(work,name));}copySafe(raw.targetReceipts?.files?.archivePath,'files.tar.gz');copySafe(raw.targetReceipts?.qdrant?.snapshotLocalPath,'qdrant.snapshot');fs.unlinkSync(path.join(work,'payload.json'));
NODE
tar -czf "$BUNDLE" -C "$WORK" .; chmod 0600 "$BUNDLE"; rm -rf "$WORK"; BYTES=$(stat -c %s "$BUNDLE"); MAX=${CHELSEA_TELEGRAM_MAX_UPLOAD_BYTES:-45000000}; [ "$BYTES" -le "$MAX" ] || { echo '{"success":false,"error":"bundle_too_large"}'; exit 8; }; SHA=$(sha256sum "$BUNDLE"|awk '{print $1}'); REQUEST_ENV="$REQUEST" PRINCIPAL_ENV="$PRINCIPAL" ACTOR_ENV="$ACTOR" BUNDLE_ENV="$BUNDLE" SHA_ENV="$SHA" BYTES_ENV="$BYTES" node <<'NODE' > "$OUTDIR/register-body.json"
console.log(JSON.stringify({p_request_id:process.env.REQUEST_ENV,p_principal_key:process.env.PRINCIPAL_ENV,p_actor_id:Number(process.env.ACTOR_ENV),p_bundle_path:process.env.BUNDLE_ENV,p_sha256:process.env.SHA_ENV,p_bytes:Number(process.env.BYTES_ENV)}));
NODE
curl -fsS --connect-timeout 10 --max-time 60 -X POST -H "Content-Type: application/json" -H "apikey: $CHELSEA_SUPABASE_SERVICE_ROLE_KEY" -H "Authorization: Bearer $CHELSEA_SUPABASE_SERVICE_ROLE_KEY" --data-binary @"$OUTDIR/register-body.json" "${CHELSEA_SUPABASE_URL%/}/rest/v1/rpc/chelsea_register_privacy_bundle_artifact_v1" -o "$OUTDIR/register.json"; REGISTER_ENV="$OUTDIR/register.json" node <<'NODE'
const fs=require('fs');let r=JSON.parse(fs.readFileSync(process.env.REGISTER_ENV,'utf8'));if(Array.isArray(r))r=r[0];if(r?.success!==true||!r.artifactId)throw new Error('privacy_bundle_pre_registration_failed');
NODE
rm -f "$OUTDIR/register-body.json" "$OUTDIR/register.json"; curl -fsS --connect-timeout 10 --max-time 300 -F "chat_id=$ACTOR" -F "caption=Экспорт данных Челси. Автоматическое удаление через 7 дней." -F "document=@$BUNDLE;type=application/gzip" "https://api.telegram.org/bot${CHELSEA_TELEGRAM_BOT_TOKEN}/sendDocument" -o "$OUTDIR/telegram.json"; BUNDLE_ENV="$BUNDLE" SHA_ENV="$SHA" BYTES_ENV="$BYTES" node <<'NODE'
const fs=require('fs');const r=JSON.parse(fs.readFileSync(process.env.BUNDLE_ENV.replace(/\/[^/]+$/,'')+'/telegram.json','utf8'));if(r.ok!==true||!r.result?.message_id)throw new Error('telegram_bundle_delivery_failed');console.log(JSON.stringify({success:true,bundlePath:process.env.BUNDLE_ENV,sha256:process.env.SHA_ENV,bytes:Number(process.env.BYTES_ENV),telegramMessageId:r.result.message_id}));
NODE
rm -f "$OUTDIR/telegram.json"
